function reportsPage(){return `${heading('CASE OPERATIONS  /  DOCUMENTATION','Reports & exports','Create reproducible report packages from reviewed findings, source citations, and method records.',button('Templates','report-templates')+button('New report','new-report','primary','plus'))}<div class="grid metrics-grid">${metric('Draft reports','2','items','Awaiting examiner review','amber','reports','')}${metric('Approved','4','exports','This case · immutable versions','teal','check','')}${metric('Cited claims','36','links','Every claim maps to evidence','blue','evidence','')}${metric('Manifest status','Ready','to build','All runs have versions','purple','database','')}</div><div class="grid lower-grid"><section class="panel"><div class="panel-heading"><div><h2>Report drafts</h2><p>Drafts are not final until examiner approval</p></div><button class="panel-link" data-action="new-report">+ New report</button></div><div class="report-list"><div class="report-card"><span class="report-icon">${icon('reports')}</span><div class="report-meta"><h3>Case findings · preliminary</h3><p>Updated 09:32 · 12 claims · 2 returned for correction</p></div><span class="status-chip partial">DRAFT</span><button class="button small" data-action="report-open">Open</button></div><div class="report-card"><span class="report-icon">${icon('reports')}</span><div class="report-meta"><h3>Evidence acquisition and custody log</h3><p>Updated 08:44 · 28 artifacts · custody events included</p></div><span class="status-chip verified">READY</span><button class="button small" data-action="report-open">Review</button></div></div></section><div class="right-stack"><section class="panel"><div class="panel-heading"><div><h2>Report integrity</h2><p>Reproducibility manifest</p></div></div><div class="checklist"><div>${icon('check')}<span>Original artifact digests recorded</span></div><div>${icon('check')}<span>Parser and model builds pinned</span></div><div>${icon('check')}<span>Reviewer decisions included</span></div><div>${icon('check')}<span>Limitations and gaps attached</span></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Export formats</h2><p>Case-approved options</p></div></div><div class="format-pills"><span>PDF · narrative</span><span>JSON · structured</span><span>CSV · observations</span></div></section></div></div>`;}
function settingsPage(){return `${heading('WORKSPACE ADMINISTRATION','Workspace settings','Manage connectors, access, processing defaults, model routing, and retention policy.',button('Audit log','audit-log')+button('Save changes','settings-save','primary'))}<div class="grid settings-grid"><section class="panel"><div class="panel-heading"><div><h2>Evidence handling</h2><p>Defaults applied to new cases</p></div></div><div class="setting-row"><span><strong>Immutable original storage</strong><small>Preserve acquired source bytes as versioned objects</small></span><button class="switch on" aria-label="Immutable original storage enabled"></button></div><div class="setting-row"><span><strong>Hash on ingestion</strong><small>Compute SHA-256 while streaming each artifact</small></span><button class="switch on" aria-label="Hash on ingestion enabled"></button></div><div class="setting-row"><span><strong>External AI egress</strong><small>Require approved route and case-level authorization</small></span><button class="switch" aria-label="External AI egress disabled"></button></div><div class="setting-row"><span><strong>Offline analysis mode</strong><small>Block worker network access by default</small></span><button class="switch on" aria-label="Offline analysis enabled"></button></div></section><section class="panel"><div class="panel-heading"><div><h2>Platform services</h2><p>Service health and current configuration</p></div><span class="status-chip verified">TARGET SERVICE MAP</span></div><div class="settings-status"><div class="system-item"><i class="system-indicator"></i><span><strong>PostgreSQL evidence registry</strong><small>Not connected · contract target only</small></span></div><div class="system-item"><i class="system-indicator"></i><span><strong>FalkorDB graph projection</strong><small>Not connected · optional graph projection</small></span></div><div class="system-item"><i class="system-indicator"></i><span><strong>Object storage</strong><small>Backend-managed storage · not connected</small></span></div><div class="system-item"><i class="system-indicator"></i><span><strong>Job workers</strong><small>Worker service · not connected</small></span></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Source connector plan</h2><p>Example integrations · not connected in this prototype</p></div><button class="button small" data-action="connect-source">Manage</button></div><div class="connector-row"><span class="connector-icon azure">ID</span><span><strong>Identity audit</strong><small>Adapter contract defined</small></span><span class="status-chip verified">DESIGN</span></div><div class="connector-row"><span class="connector-icon cloud-icon">SP</span><span><strong>SharePoint audit</strong><small>Provider API pending implementation</small></span><span class="status-chip partial">DESIGN</span></div><div class="connector-row"><span class="connector-icon net-icon">NW</span><span><strong>Network sensor</strong><small>Health endpoint pending implementation</small></span><span class="status-chip partial">DESIGN</span></div></section><section class="panel"><div class="panel-heading"><div><h2>Retention & access</h2><p>Case policy controls</p></div></div><div class="detail-list"><div><span>Default retention</span><strong>365 days · review at 30 days</strong></div><div><span>Legal hold</span><strong>Off · case lead approval required</strong></div><div><span>Model policy</span><strong>Local models for restricted evidence</strong></div><div><span>Audit storage</span><strong>Append-only · separate backup</strong></div></div></section></div>`;}

const renderers={overview,evidence:evidencePage,coverage:coveragePage,timeline:timelinePage,entities:entitiesPage,agents:()=>renderAgentHub(agentHubData),media:mediaPage,deepfake:()=>renderDeepfakePage({mode:repository.mode,evidence,selectedId:selectedSignalId,runs:deepfakeRuns}),review:reviewPage,acquisitions:acquisitionsPage,reports:reportsPage,settings:settingsPage};
function route(){
 const page=(location.hash||'#overview').slice(1);const selected=renderers[page]?page:'overview';
 if(selected!=='deepfake'&&deepfakePollTimer){clearInterval(deepfakePollTimer);deepfakePollTimer=null;}
 document.querySelectorAll('.nav-item[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===selected));
 document.querySelector('.breadcrumbs strong').textContent=selected==='overview'?workspace?.case.id||config.caseId:titles[selected];
 if(!workspace){pageContent.innerHTML='<div class="loading-state" role="status"><span class="loading-spinner"></span><strong>Opening case workspace</strong><span>Loading the selected case snapshot…</span></div>';return;}
  if(repository.mode==='api'&&selected==='deepfake'){loadDeepfakePage();if(!deepfakePollTimer)deepfakePollTimer=setInterval(()=>{if(location.hash==='#deepfake'&&!document.hidden)loadDeepfakePage({force:true});},15000);return;}
  if(selected==='agents'){loadAgentHubPage();return;}
  if(repository.mode==='demo'&&selected==='entities'){
   pageContent.innerHTML=renderApiPage(demoRelationshipPage());
   pageContent.querySelector('.graph-agent-panel')?.remove();
   document.title='Evidence relationship graph — Forensic Atlas';
   window.scrollTo({top:0,behavior:'instant'});return;
  }
  if(repository.mode==='api'&&selected!=='overview'){loadRemotePage(selected);return;}
 pageContent.innerHTML=renderers[selected]();document.title=`${titles[selected]} — Forensic Atlas`;window.scrollTo({top:0,behavior:'instant'});
}
function renderCitedSummary(data){
 const result=data?.latestSummary, provider=data?.summaryProvider||{}, ready=provider.ready===true;
 const rows=(result?.statements||[]).map(item=>`<li><span class="agent-state ${escapeHtml(item.state)}">${escapeHtml(item.state)}</span><div><p>${escapeHtml(item.text)}</p><small>${escapeHtml(item.origin)} · ${escapeHtml((item.sources||[]).join(' · '))}</small></div></li>`).join('');
 return `<section id="caseSummaryPanel" class="panel cited-summary-panel" aria-busy="${summaryBusy}"><div class="panel-heading"><div><span class="eyebrow">PHASE 2 · LOCAL MODEL</span><h2>Cited case summary</h2><p>The model selects and orders verified evidence statements. Every statement keeps its original wording and source trail.</p></div><button class="button primary" data-action="summary-generate" ${!ready||summaryBusy?'disabled':''}>${summaryBusy?'Preparing draft…':result?'Generate new draft':'Generate cited draft'}</button></div><div class="summary-model-strip"><span class="agent-state ${ready?'derived':'unknown'}">${ready?'LOCAL MODEL READY':'MODEL OFFLINE'}</span><span>${escapeHtml(provider.upstreamModel||'Local model not configured')}${provider.quantization?' · '+escapeHtml(provider.quantization):''}</span>${result?`<span>Draft · ${escapeHtml(formatUtc(result.createdAt))}</span>`:''}</div><p class="summary-run-status" role="status" aria-live="polite">${ready?'':'Start the local model service, then refresh this view to generate a draft.'}</p>${rows?`<ol class="summary-statements">${rows}</ol><details class="summary-provenance"><summary>Citations and verification</summary><p>Exact source statements and evidence states passed verification. This does not validate the underlying source evidence.</p><small>Summary ${escapeHtml(result.summaryId)} · ${escapeHtml(result.method)} · ${(result.elapsedMs/1000).toFixed(1)} s</small><small>Context digest ${escapeHtml(result.contextDigest)}</small><ol>${(result.inputContext?.trace||[]).map(item=>`<li>${escapeHtml(item.tool)}${item.pathCount!=null?' · '+escapeHtml(item.pathCount)+' paths':''}</li>`).join('')}</ol></details>`:'<div class="summary-empty">Generate a short draft from the case read model and bounded graph paths. The result remains subject to examiner review.</div>'}<div class="summary-draft-note">Unreviewed extractive draft · original evidence bytes are not examined by this workflow.</div></section>`;
}
async function generateCitedSummary(){
 if(summaryBusy)return;
 summaryBusy=true;
 const panel=document.getElementById('caseSummaryPanel');
 const trigger=panel?.querySelector('[data-action="summary-generate"]');
 const status=panel?.querySelector('.summary-run-status');
 panel?.setAttribute('aria-busy','true');
 if(trigger){trigger.disabled=true;trigger.textContent='Preparing draft…';}
 if(status)status.textContent='Retrieving case facts, running the local model, and verifying the selected citations. This may take up to two minutes.';
 try{
  await repository.generateCaseSummary(workspace.case.id);
  agentHubData=await repository.loadAgentHub(workspace.case.id);
  summaryBusy=false;
  if(location.hash==='#agents'){pageContent.innerHTML=renderAgentHub(agentHubData);document.getElementById('caseSummaryPanel')?.scrollIntoView({block:'start'});}
 }catch(error){if(status){status.setAttribute('role','alert');status.textContent=error.message||'The summary could not be generated. No replacement draft was substituted.';}}
 finally{summaryBusy=false;panel?.setAttribute('aria-busy','false');if(trigger){trigger.disabled=agentHubData?.summaryProvider?.ready!==true;trigger.textContent='Generate cited draft';}}
}
function renderSavedMediaContext(data){
 const context=data?.latestRun?.mediaInspectionContext;
 if(!context)return `<section class="panel cited-summary-panel"><div class="panel-heading"><div><span class="eyebrow">PHASE 6 · MEDIA → AGENTS</span><h2>Saved media observations</h2><p>Run case synthesis to load saved inspections into the agent workflow.</p></div><button class="button" data-action="agents-run">Read inspection context</button></div></section>`;
 const rows=(context.facts||[]).map(item=>`<li><span class="agent-state derived">${escapeHtml(item.state)}</span><div><p>${escapeHtml(item.text)}</p><small>Sources: ${escapeHtml(item.sources.join(' · '))}</small></div></li>`).join('');
 return `<section class="panel cited-summary-panel"><div class="panel-heading"><div><span class="eyebrow">PHASE 6 · MEDIA → AGENTS</span><h2>Saved media observations</h2><p>${escapeHtml(context.summary)}</p></div><a class="button" href="#media">Inspect media →</a></div>${rows?`<ol class="summary-statements">${rows}</ol>`:'<div class="summary-empty">No usable saved inspection was returned. Inspect an uploaded media file, then run case synthesis again.</div>'}<p class="memory-recall-note">Historical observations · not refreshed byte checks · no authenticity finding</p><ul class="memory-recall-note">${(context.items||[]).map(item=>`<li>${escapeHtml(item.artifactId)}: ${escapeHtml(item.nextStep)}</li>`).join('')}</ul></section>`;
}
function renderAgentHub(data){
 const run=data?.latestRun;
 const cards=(run?.workstreams||[]).map(item=>`<article class="agent-workstream"><div class="agent-workstream-top"><span class="agent-glyph">${icon(item.agentId==='media-forensics'?'deepfake':item.agentId==='graph-context'?'entities':item.agentId==='timeline-correlation'?'timeline':'shield')}</span><span class="agent-state ${escapeHtml(item.state||'unknown')}">${escapeHtml((item.state||'unknown').replace(/-/g,' '))}</span></div><h3>${escapeHtml(item.name)}</h3><p>${escapeHtml(item.summary)}</p><div class="agent-citations"><strong>Case sources</strong><span>${escapeHtml((item.sources||[]).join(' · ')||'No source IDs returned')}</span></div><div class="agent-impact"><strong>Potential impact</strong><p>${escapeHtml(item.impact||'No impact assessment available.')}</p></div>${item.alternatives?.length?`<details><summary>Alternative explanations</summary><ul>${item.alternatives.map(value=>`<li>${escapeHtml(value)}</li>`).join('')}</ul></details>`:''}<div class="agent-next"><strong>Examiner next step</strong><span>${escapeHtml(item.nextStep||'Review source material.')}</span></div></article>`).join('');
 const roster=(data?.roster||[]).map(item=>`<div class="agent-roster-row"><span class="agent-roster-dot ${escapeHtml(item.status)}"></span><div><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.domain)} · ${escapeHtml(item.mode)}</small></div><span class="agent-roster-status">${escapeHtml(item.status)}</span><p>${escapeHtml(item.description)}</p></div>`).join('');
 const research=(run?.research||[]).map(item=>`<a class="research-source" href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer"><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.organization)} · ${escapeHtml(item.use)}</small></span><span aria-hidden="true">↗</span></a>`).join('');
 const limits=(run?.limits||['No synthesis has been run for this case yet.']).map(item=>`<li>${escapeHtml(item)}</li>`).join('');
 const providers=data?.provider||{llm:'not-configured',mediaDetector:'not-configured',graph:'not-connected'};
 const memory=(data?.memory||[]).slice(0,6).map(item=>`<li><strong>${escapeHtml(item.kind||'episode')} · ${escapeHtml(item.agentId||'agent')}</strong><span>${escapeHtml(item.summary||'No summary')}</span><small>${escapeHtml(item.evidenceState||'unknown')} · ${(item.sourceIds||[]).map(escapeHtml).join(' · ')||'no source references'}</small></li>`).join('');
 const triage=(run?.reviewTriage?.orderedItems||[]).map(item=>`<li class="triage-item"><span class="triage-rank">${escapeHtml(item.rank)}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.rationale)}</p><small>${escapeHtml(item.category)} · ${(item.sourceIds||[]).map(escapeHtml).join(' · ')||'no case source matched'}</small><span>${escapeHtml(item.nextStep)}</span></div><a href="#review" aria-label="Open review queue">Review</a></li>`).join('');
 const coordination=`<section class="panel agent-memory"><div class="panel-heading"><div><h2>Shared case memory</h2><p>Recent graph-backed episodes with evidence state and source trail</p></div><span class="panel-kicker">FALKORDB</span></div>${memory?`<ol>${memory}</ol>`:'<p>No case episodes have been recorded yet.</p>'}</section>`;
 return `${heading('CASE INTELLIGENCE  /  SPECIALIST AGENTS','Hybrid agent hub','A coordinated forensic workflow that links evidence coverage, graph context, media screening, timeline review, and research guidance.',button(run?'Run agents again':'Run case synthesis','agents-run','primary','arrow'))}${renderCitedSummary(data)}${renderSavedMediaContext(data)}${renderMemoryRecall(data,evidence)}${renderHandoffInbox(data?.handoffs||[])}<section class="agent-hub-status"><div><span class="eyebrow">PROVIDER STATUS</span><strong>${run?escapeHtml(run.runId)+' · '+escapeHtml(formatUtc(run.createdAt)):'Ready for a case-scoped run'}</strong><small>Local rule and tool agents are active; optional model providers report their actual configuration.</small></div><div class="provider-pills"><span>Graph <b>${escapeHtml(providers.graph)}</b></span><span>LLM <b>${escapeHtml(providers.llm)}</b></span><span>Media model <b>${escapeHtml(providers.mediaDetector)}</b></span></div></section>${run?`<section class="agent-priority-panel"><div class="panel-heading"><div><h2>Cross-layer examiner priorities</h2><p>${escapeHtml(run.headline)} · ${escapeHtml(run.evidenceCount)} detail rows / ${escapeHtml(run.evidenceOverviewCount)} overview items · ${escapeHtml(run.openReviewCount)} open reviews</p></div><span class="panel-kicker">${escapeHtml(run.mode||'TOOL GROUNDED')}</span></div><ol>${(run.priorities||[]).map((item,index)=>`<li><i>${index+1}</i><span>${escapeHtml(item)}</span></li>`).join('')}</ol></section><section class="panel triage-panel"><div class="panel-heading"><div><h2>Review sequence</h2><p>Deterministic queue ordering from source dependencies and item type; examiner retains every decision</p></div><span class="panel-kicker">${(run.reviewTriage?.orderedItems||[]).length} OPEN</span></div>${triage?`<ol>${triage}</ol>`:'<p>No open review items were returned.</p>'}</section><section class="agent-workstream-grid">${cards}</section><section class="panel agent-roster-panel"><div class="panel-heading"><div><h2>Coordinated specialist roster</h2><p>Specialists, their method, and live availability for this case</p></div><span class="panel-kicker">${(data?.roster||[]).length} AGENTS</span></div><div class="agent-roster-grid">${roster}</div></section>${coordination}<section class="agent-lower-grid"><div class="panel"><div class="panel-heading"><div><h2>Research mapped to this workflow</h2><p>Primary guidance with concrete use in the investigation pipeline</p></div></div><div class="research-source-list">${research}</div></div><div class="panel"><div class="panel-heading"><div><h2>Operating limits</h2><p>Run-specific model and evidence constraints</p></div></div><ul class="agent-limits">${limits}</ul><div class="banner">Cause, impact, and relationships remain candidate explanations until an examiner checks source records and alternatives.</div></div></section>`:`<section class="panel agent-empty"><span class="agent-empty-icon">${icon('entities')}</span><h2>Run a coordinated case synthesis</h2><p>Specialists will inspect the case read model, graph connection, media configuration, unresolved review items, and research guidance. Each result includes case artifact IDs, limitations, alternatives, and a next review step.</p><button class="button primary" data-action="agents-run">Start case synthesis</button></section><section class="panel agent-roster-panel"><div class="panel-heading"><div><h2>Specialist roster</h2><p>Bounded agents coordinated for this case</p></div><span class="panel-kicker">${(data?.roster||[]).length} AGENTS</span></div><div class="agent-roster-grid">${roster}</div></section>${coordination}`}`;
}
async function loadAgentHubPage({run=false}={}){
 pageController?.abort();const controller=new AbortController();pageController=controller;const requestId=++pageRequestId;pageContent.innerHTML='<div class="loading-state" role="status"><span class="loading-spinner"></span><strong>Coordinating specialist agents</strong><span>Reading case-scoped data and provider availability…</span></div>';
 try{if(repository.mode!=='api')throw new Error('The Hybrid Agent Hub requires the case API.');if(run){await repository.runAgentHub(workspace.case.id);agentHubData=await repository.loadAgentHub(workspace.case.id,{signal:controller.signal});}else{agentHubData=await repository.loadAgentHub(workspace.case.id,{signal:controller.signal});}if(requestId!==pageRequestId||location.hash.slice(1)!=='agents')return;pageContent.innerHTML=renderAgentHub(agentHubData);document.title=`${titles.agents} — Forensic Atlas`;window.scrollTo({top:0,behavior:'instant'});}
 catch(error){if(error.name==='AbortError'||requestId!==pageRequestId)return;pageContent.innerHTML=`<section class="load-error" role="alert"><span class="load-error-mark">!</span><div><p class="eyebrow">AGENT HUB UNAVAILABLE</p><h1>We could not load the case agents</h1><p>${escapeHtml(error.message||'The case service could not be reached.')}</p><small>No demo analysis has been substituted.</small><button class="button primary" data-action="agents-refresh">Try again</button></div></section>`;}
}
function renderLoadError(error){
 const detail=repository.mode==='api'?escapeHtml(error?.message||'The case service could not be reached.'):'The local demo snapshot could not be loaded.';
 pageContent.innerHTML=`<section class="load-error" role="alert"><span class="load-error-mark">!</span><div><p class="eyebrow">CASE WORKSPACE UNAVAILABLE</p><h1>We could not load this case</h1><p>${detail}</p><small>${repository.mode==='api'?'No demo records have been substituted for live case data.':''}</small><button class="button primary" data-action="retry-load">Try again</button></div></section>`;
}
function renderApiPage(data){
 const citedReports=data.title==='Evidence relationship graph'?renderEntityMap(data.relationshipGraph):data.title==='Reports & exports'?renderCitedReports(data,workspace.case.id):data.title==='Media analysis'?renderMediaInspection(data):'';
 const actions=button('Refresh data','page-refresh','','clock')+(data.title==='Evidence library'?button('Add evidence','upload-evidence','primary','plus'):'');
 const metrics=data.metrics.map((item)=>metric(escapeHtml(item.label),escapeHtml(item.value),escapeHtml(item.unit||''),escapeHtml(item.foot||''),['teal','blue','amber','purple'].includes(item.kind)?item.kind:'blue',item.icon||'file')).join('');
 const columns=data.columns;
 const rows=data.rows.map((row)=>`<tr>${columns.map((column)=>{const value=row?.[column.key];const text=value==null?'—':typeof value==='object'?JSON.stringify(value):String(value);return `<td>${escapeHtml(text)}</td>`;}).join('')}${data.title==='Evidence library'?`<td><a class="text-action" href="/api/v1/cases/${encodeURIComponent(config.caseId)}/artifacts/${encodeURIComponent(row.id)}/download">Download</a></td>`:''}</tr>`).join('');
 const memory=(data.agentMemory||[]).map(item=>`<li><strong>${escapeHtml(item.question)}</strong><span>${escapeHtml(item.answer)}</span><small>${escapeHtml(item.entity_id)} · ${escapeHtml((item.sources||[]).join(', ')||'no source IDs')}</small></li>`).join('');
 const graphAgent=data.title==='Evidence relationship graph'?`<section class="panel graph-agent-panel"><div class="panel-heading"><div><h2>Evidence path agent</h2><p>Ask a question about how a selected entity connects to case evidence.</p></div><span class="panel-kicker">FALKORDB · TRACEABLE</span></div><div class="banner">${icon('shield')}<span>The agent follows bounded graph paths and returns source IDs. Candidate edges stay labeled as hypotheses; no identity or causation conclusion is generated.</span></div><form id="graphAgentForm" class="graph-agent-form"><div class="form-field"><label for="graphEntityId">Starting entity</label><select id="graphEntityId" name="entityId" ${data.rows.length?'':'disabled'}>${data.rows.map(row=>`<option value="${escapeHtml(row.id)}">${escapeHtml(row.name)} · ${escapeHtml(row.id)}</option>`).join('')}</select></div><div class="form-field graph-question-field"><label for="graphQuestion">Investigation question</label><input id="graphQuestion" name="question" maxlength="500" value="What evidence-linked entities connect to this record?" required /></div><button class="button primary" ${data.rows.length?'':'disabled'}>Trace paths</button></form><div id="graphAgentResult" class="graph-agent-result" role="status">${data.rows.length?'The graph traversal will show each path, relation state, and source artifact.':'FalkorDB is not connected. Start the graph service and load the case projection to enable graph reasoning.'}</div><section class="agent-memory"><div class="panel-heading"><div><h3>Persistent agent memory</h3><p>Recent questions and source trails saved for this case</p></div></div>${memory?`<ol>${memory}</ol>`:`<p>No graph queries have been saved yet.</p>`}</section></section>`:'';
 return `${heading('CASE WORKSPACE  /  API READ MODEL',escapeHtml(data.title),escapeHtml(data.summary),actions)}${citedReports}${metrics?`<div class="grid metrics-grid">${metrics}</div>`:''}<section class="panel"><div class="panel-heading"><div><h2>${escapeHtml(data.sectionTitle||'Case records')}</h2><p>${escapeHtml(data.sectionDescription||'Records returned by the case service')}</p></div><span class="panel-kicker">${data.rows.length} RECORDS</span></div>${rows?`<div class="table-wrap"><table class="data-table"><thead><tr>${columns.map((column)=>`<th>${escapeHtml(column.label)}</th>`).join('')}${data.title==='Evidence library'?'<th>Action</th>':''}</tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty-state"><span>${icon('file')}</span><strong>No records in this view</strong><small>The case service returned an empty result set.</small></div>`}<div class="panel-footer"><span>API read model · ${escapeHtml(data.updatedAt||'timestamp unavailable')}</span><span>Page contract v1</span></div></section>${graphAgent}`;
}
async function loadRemotePage(page,{force=false}={}){
 const cached=pageCache.get(page);
 if(!force&&page!=='reports'&&cached&&Date.now()-cached.loadedAt<30000){pageContent.innerHTML=renderApiPage(cached.data);return;}
 pageController?.abort();const controller=new AbortController();pageController=controller;const requestId=++pageRequestId;
 pageContent.innerHTML='<div class="loading-state" role="status"><span class="loading-spinner"></span><strong>Loading case view</strong><span>Requesting the page read model…</span></div>';
 try{const data=await repository.loadPage(workspace.case.id,page,{signal:controller.signal});if(requestId!==pageRequestId||location.hash.slice(1)!==page)return;pageCache.set(page,{data,loadedAt:Date.now()});pageContent.innerHTML=renderApiPage(data);}
 catch(error){if(error.name==='AbortError'||requestId!==pageRequestId)return;pageContent.innerHTML=`<section class="load-error" role="alert"><span class="load-error-mark">!</span><div><p class="eyebrow">${escapeHtml(titles[page]||'CASE VIEW')} UNAVAILABLE</p><h1>We could not load this case view</h1><p>${escapeHtml(error.message||'The case service could not be reached.')}</p><small>No fictional records were substituted for API data.</small><button class="button primary" data-action="page-refresh">Try again</button></div></section>`;}
}
async function loadDeepfakePage({force=false}={}){
 const cached=pageCache.get('deepfakeRuns');if(!force&&cached&&Date.now()-cached.loadedAt<30000){deepfakeRuns=cached.data;pageContent.innerHTML=renderers.deepfake();return;}
 pageController?.abort();const controller=new AbortController();pageController=controller;const requestId=++pageRequestId;pageContent.innerHTML='<div class="loading-state" role="status"><span class="loading-spinner"></span><strong>Loading media signals</strong><span>Reading case-scoped detector runs…</span></div>';
 try{const runs=await repository.loadDeepfakeRuns(workspace.case.id,{signal:controller.signal});if(requestId!==pageRequestId||location.hash.slice(1)!=='deepfake')return;deepfakeRuns=runs;pageCache.set('deepfakeRuns',{data:runs,loadedAt:Date.now()});const newFlags=runs.filter(run=>run.status==='completed'&&run.signals.length&&!seenDeepfakeAlerts.has(run.id));runs.forEach(run=>seenDeepfakeAlerts.add(run.id));if(newFlags.length){const badge=document.querySelector('.notification-button i');if(badge)badge.style.display='block';toast(newFlags.length+' media analysis result'+(newFlags.length===1?'':'s')+' flagged for examiner review.');}pageContent.innerHTML=renderers.deepfake();}
 catch(error){if(error.name==='AbortError'||requestId!==pageRequestId)return;pageContent.innerHTML='<section class="load-error" role="alert"><span class="load-error-mark">!</span><div><p class="eyebrow">DEEPFAKE SIGNALS UNAVAILABLE</p><h1>We could not load detector runs</h1><p>'+escapeHtml(error.message||'The case service could not be reached.')+'</p><small>No demo scores were substituted for API data.</small><button class="button primary" data-action="deepfake-refresh">Try again</button></div></section>';}
}
async function boot(){
 pageContent.innerHTML='<div class="loading-state" role="status"><span class="loading-spinner"></span><strong>Opening case workspace</strong><span>Loading the selected case snapshot…</span></div>';
 try{
  workspace=await repository.loadWorkspace(config.caseId);evidence=workspace.evidence;reviewItems=workspace.reviewItems;sourceCoverage=workspace.sourceCoverage;events=workspace.events;
  const workspaceName=document.querySelector('.workspace-switcher strong');
  if(workspaceName)workspaceName.textContent=workspace.case.workspaceName||'Northstar Lab';
  const status=document.getElementById('dataSourceStatus');if(status)status.textContent=repository.mode==='api'?'API snapshot ready':'Demo snapshot · fictional data';
  const caseState=document.getElementById('caseStateLabel');if(caseState)caseState.textContent=String(workspace.case.status||'active_review').replace(/[_-]/g,' ').toUpperCase();
  const evidenceCount=document.querySelector('[data-page="evidence"] .nav-count');if(evidenceCount)evidenceCount.textContent=workspace.overview.evidenceItems;
  const reviewCount=document.querySelector('[data-page="review"] .review-count');if(reviewCount)reviewCount.textContent=workspace.overview.reviewQueueItems;
  route();
 }catch(error){renderLoadError(error);}
}
