  if(action==='deepfake-notifications'){openNotifications();return;}
  if(action==='deepfake-select'){const keepInspector=document.querySelector('.deepfake-layout')?.classList.contains('inspector-open');selectedSignalId=nav.dataset.id||'ART-025';pageContent.innerHTML=renderDeepfakePage({mode:repository.mode,evidence,selectedId:selectedSignalId,runs:deepfakeRuns});if(keepInspector)document.querySelector('.deepfake-layout')?.classList.add('inspector-open');return;}
