  if(action==='deepfake-inspector'){document.querySelector('.deepfake-layout')?.classList.add('inspector-open');return;}
  if(action==='deepfake-inspector-close'){document.querySelector('.deepfake-layout')?.classList.remove('inspector-open');return;}
  if(action==='deepfake-seek'){let progress=Number(nav.dataset.progress);if(nav.classList.contains('waveform-track')){const rect=nav.getBoundingClientRect();progress=Math.max(0,Math.min(100,(e.clientX-rect.left)/rect.width*100));const seconds=138*progress/100;nav.setAttribute('aria-valuenow',seconds.toFixed(1));nav.dataset.time=Math.floor(seconds/60).toString().padStart(2,'0')+':'+(seconds%60).toFixed(1).padStart(4,'0');}const frame=document.getElementById('deepfakeFrameTime');if(frame)frame.textContent=nav.dataset.time||'00:00:00';if(Number.isFinite(progress))document.querySelectorAll('.editor-playhead').forEach(head=>head.style.left=progress+'%');document.querySelectorAll('.span-row').forEach(row=>row.classList.toggle('active',row===nav.closest('.span-row')));return;}
  if(action==='deepfake-play'){nav.textContent=nav.textContent.trim()==='▶'?'Ⅱ':'▶';toast(repository.mode==='demo'?'Preview control only; no source media is loaded.':'Preview playback requires a media stream from the case service.');return;}
  if(action==='deepfake-method'&&repository.mode==='api'){modal('Research audio screening scope',"<p>AASIST-L is an MIT-licensed pretrained ASVspoof2019 LA audio anti-spoofing baseline. This integration applies overlapping 4.04-second windows to speech audio. It does not inspect video pixels.</p><p>Local smoke testing over-flagged known natural speech. Softmax outputs and the 0.35/0.75 display thresholds are not calibrated authenticity probabilities. Short inputs, music, noise, languages and unseen generators can be unreliable. Green is not verified real; red requires review.</p>",'Understood');return;}
  if(action==='deepfake-method'){modal('Detector method and scope',"<div class='detail-list'><div><span>Detector families</span><strong>Frame texture · temporal consistency · audio/video sync</strong></div><div><span>Evaluation</span><strong>Celeb-DF + DFDC · cross-set scope</strong></div><div><span>Output meaning</span><strong>Triage score, not probability of truth</strong></div><div><span>Review policy</span><strong>Examiner confirmation required before a finding</strong></div></div><div class='banner' style='margin-top:14px'>Compression, edits, short duration, domain shift, and unseen generation methods may cause false alarms or missed signals. Preserve the original and cite exact spans.</div>",'Understood');return;}
  if(action==='deepfake-policy'){modal('Automatic media screening',"<div class='detail-list'><div><span>Trigger</span><strong>New image, audio, or video artifact registered to the case</strong></div><div><span>Guardrails</span><strong>Confirm authority and scope; preserve and hash original bytes</strong></div><div><span>Processing</span><strong>Analyze derived copies with versioned local models</strong></div><div><span>Notification</span><strong>Completed runs with localized signals enter examiner review</strong></div></div><div class='banner' style='margin-top:14px'>This interface defines the workflow. The case service must implement the intake trigger, detector workers, result persistence, and event delivery.</div>",'Understood');return;}
  if(action==='deepfake-review'){location.hash='review';toast('Open the review queue to add a case decision with rationale.');return;}
  if(action==='deepfake-run'){const artifactId=nav.dataset.id||(repository.mode==='demo'?'ART-025':evidence.find(item=>/video|audio|image|media/i.test(item.type||''))?.id);if(!artifactId){toast('Register a media artifact before queuing analysis.');return;}nav.disabled=true;try{const response=await repository.queueMediaAnalysis(workspace.case.id,{artifactId,profile:'multimodal-screening',modelRoute:'local-validated'});if(repository.mode==='demo'){toast('Demo request recorded locally. No detector ran; sample flags remain illustrative.');}else{toast(response?.data?.message||'Analysis request recorded.');pageCache.delete('deepfakeRuns');await loadDeepfakePage({force:true});}}catch(error){toast('Could not queue media analysis: '+error.message);}finally{nav.disabled=false;}return;}
  if(action==='retry-load'){boot();return;}
  if(action==='agents-run'){loadAgentHubPage({run:true});return;}
  if(action==='summary-generate'){generateCitedSummary();return;}
  if(action==='agents-refresh'){loadAgentHubPage();return;}
  if(action==='page-refresh'){loadRemotePage(location.hash.slice(1),{force:true});return;}
 if(action==='upload-evidence'){modal('Add evidence',`<div class="banner">${icon('shield')}<span>Local development intake stores the uploaded bytes and registers SHA-256. This is not a certified evidence vault or a complete chain-of-custody process.</span></div><div class="form-field" style="margin-top:14px"><label for="evidenceFile">File · maximum 512 MB</label><input id="evidenceFile" name="file" type="file" required /></div><div class="form-field"><label for="mediaType">Artifact type</label><select id="mediaType" name="media_type"><option>Video</option><option>Audio</option><option>Image</option><option>Document</option><option>Disk image</option><option>Log / export</option><option>Other</option></select></div><div class="form-field"><label for="sourceLabel">Source / intake note</label><input id="sourceLabel" name="source_label" value="Local examiner intake" maxlength="250" required /></div>`,'Store and hash',async form=>{const response=await repository.uploadEvidence(workspace.case.id,form);workspace=await repository.loadWorkspace(config.caseId);evidence=workspace.evidence;pageCache.clear();route();return response;});return;}
 if(action==='new-acquisition'||action==='preservation'){acquisitionModal();return;}
  if(action==='export'||action==='manifest'||action==='timeline-export'||action==='review-export'){modal(action==='export'?'Export case brief':'Build export package',`<div class="banner">${icon('warning')}<span>Only reviewed, case-authorized material belongs in a final package. The service records its manifest and digest.</span></div><div class="form-field" style="margin-top:14px"><label for="exportContents">Package contents</label><select id="exportContents" name="contents"><option value="brief">Case summary + reviewed findings + custody appendix</option><option value="manifest">Evidence manifest + provenance only</option><option value="timeline">Timeline observations + source links</option></select></div><div class="form-field"><label for="exportFormat">Output format</label><select id="exportFormat" name="format"><option value="pdf-json">PDF + JSON manifest</option><option value="pdf">PDF only</option><option value="json-csv">JSON + CSV</option></select></div>`,'Prepare export',async form=>repository.createExport(workspace.case.id,formValues(form)));return;}
  if(action==='new-report'){modal('Start a report',`<div class="form-field"><label for="reportTitle">Report title</label><input id="reportTitle" name="title" value="Case findings · preliminary" required /></div><div class="form-field"><label for="reportTemplate">Template</label><select id="reportTemplate" name="template"><option value="evidence-linked">Evidence-linked investigation report</option><option value="custody">Chain of custody</option><option value="media-appendix">Media analysis appendix</option></select></div><div class="form-field"><label for="reportScope">Include</label><select id="reportScope" name="scope"><option value="reviewed">Reviewed claims only</option><option value="reviewed-with-limitations">Reviewed claims and unresolved alternatives</option></select></div>`,'Create draft',async form=>repository.createReport(workspace.case.id,formValues(form)));return;}
  if(action==='review-approve'){const id=nav.dataset.id;if(!id)return;nav.disabled=true;try{await repository.recordReviewDecision(workspace.case.id,id,'reviewed');reviewItems=reviewItems.filter(item=>item.id!==id);workspace.overview.reviewQueueItems=Math.max(0,workspace.overview.reviewQueueItems-1);const badge=document.querySelector('[data-page="review"] .review-count');if(badge)badge.textContent=workspace.overview.reviewQueueItems;route();toast(repository.mode==='demo'?'Demo decision recorded locally. No backend was contacted.':'Review decision saved.');}catch(error){nav.disabled=false;toast(`Could not save review decision: ${error.message}`);}return;}
  if(action==='review-return'){const id=nav.dataset.id;if(!id)return;nav.disabled=true;try{await repository.recordReviewDecision(workspace.case.id,id,'returned');reviewItems=reviewItems.filter(item=>item.id!==id);workspace.overview.reviewQueueItems=Math.max(0,workspace.overview.reviewQueueItems-1);const badge=document.querySelector('[data-page="review"] .review-count');if(badge)badge.textContent=workspace.overview.reviewQueueItems;route();toast(repository.mode==='demo'?'Demo draft returned locally. No backend was contacted.':'Draft returned to the case workflow.');}catch(error){nav.disabled=false;toast(`Could not return review item: ${error.message}`);}return;}
  if(action==='review-open'){const item=reviewItems.find(entry=>entry.id===nav.dataset.id);if(!item)return;modal('Examiner review',`<div class="detail-list"><div><span>Review item</span><strong>${escapeHtml(item.id)}</strong></div><div><span>Claim type</span><strong>${escapeHtml(item.type)}</strong></div><div><span>Claim</span><strong>${escapeHtml(item.title)}</strong></div><div><span>Evidence reference</span><strong>${escapeHtml(item.evidence)}</strong></div><div><span>Model score</span><strong>${escapeHtml(item.score)}</strong></div></div><div class="banner" style="margin-top:14px">${icon('warning')}<span>Automated outputs are advisory. Record a decision only after inspecting the underlying source and method record.</span></div>`,'Close');return;}
  if(action==='artifact'){const item=evidence.find(entry=>entry.id===nav.dataset.id);if(!item)return;modal(`Artifact · ${item.id}`,`<div class="detail-list"><div><span>Name</span><strong>${escapeHtml(item.name)}</strong></div><div><span>Type</span><strong>${escapeHtml(item.type)}</strong></div><div><span>Source</span><strong>${escapeHtml(item.source)}</strong></div><div><span>Acquired</span><strong>${escapeHtml(item.date)}</strong></div><div><span>Size</span><strong>${escapeHtml(item.size)}</strong></div><div><span>Listed integrity state</span><strong>${escapeHtml(item.status)}</strong></div></div><div class="banner" style="margin-top:14px">${icon('warning')}<span>This list summary is not a substitute for source bytes, acquisition metadata, or full custody history.</span></div>`,'Close');return;}
  if(action==='job-details'||action==='report-open'||action==='case-details'){modal(action==='job-details'?`Job details · ${nav.dataset.id||'JOB-088'}`:action==='report-open'?'Report review':'Case details',`<div class="detail-list"><div><span>Case</span><strong>${escapeHtml(workspace.case.id)}</strong></div><div><span>Evidence reference</span><strong>ART-028 · source record 442</strong></div><div><span>Integrity</span><strong>Digest state shown in evidence list</strong></div><div><span>Interpretation state</span><strong>Candidate / requires examiner review</strong></div></div><div class="banner" style="margin-top:14px">${icon('warning')}<span>Review source records and custody details before accepting a conclusion.</span></div>`,'Close');return;}
  if(action==='modal-close'){if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-action="modal-close"]')){document.getElementById('modalRoot').innerHTML='';modalSubmit=null;}return;}
  if(action==='modal-confirm'){const form=nav.closest('.modal')?.querySelector('.modal-body');const invalid=[...(form?.querySelectorAll('[required]')||[])].find(field=>!field.checkValidity());if(invalid){invalid.reportValidity();return;}nav.disabled=true;try{const submitted=Boolean(modalSubmit);const result=modalSubmit&&form?await modalSubmit(form):null;document.getElementById('modalRoot').innerHTML='';modalSubmit=null;const label=!submitted?'Acknowledged.':repository.mode==='demo'?'Demo request saved locally; no service was contacted.':(result?.data?.message||'Request submitted to the case service.');toast(label);}catch(error){nav.disabled=false;toast(`Request failed: ${error.message}`);}return;}
 if(action==='job-pause'){toast('Demo action: acquisition job paused.');return;}
