 if(action==='review-guide'||action==='model-info'||action==='help'){modal(action==='model-info'?'Media model methodology':'Investigator guide',`<p class="modal-copy">This prototype uses fictional records to demonstrate the interface. Real deployment requires validated source adapters, case authorization, model-version records, evidence-linked claims, and examiner approval.</p><div class="banner">${icon('shield')}<span>Hashes establish post-capture byte integrity; they do not independently establish source authenticity.</span></div>`,'Understood');return;}
 if(action==='settings-save'||action==='connect-source'||action==='scope-plan'||action==='audit-log'||action==='report-templates'||action==='job-history'||action==='filters'||action==='hypothesis'||action==='annotation'||action==='lineage'||action==='inspect-link'||action==='review-sort'||action==='load-more'){toast('This control is wired as a design prototype; service integration comes next.');return;}
